/**
 * `virtual:c15t/options` is generated by the `c15t()` integration's Vite
 * plugin. `@c15t/astro` declares it for its own sources but does not ship
 * the declaration, so the app restates it — as `| null`, because the
 * zero-consent `baseline` build stubs it out (see `astro.config.mjs`).
 */
declare module 'virtual:c15t/options' {
	import type { C15tResolvedOptions } from '@c15t/astro';

	const options: C15tResolvedOptions | null;
	export default options;
}
